import unittest

from solution import downgrade, upgrade


class SchemaMigrationTests(unittest.TestCase):
    def make_schema(self):
        return {
            "documents": {
                "source": {
                    "type": "text",
                    "nullable": "previous",
                    "options": {"languages": ["en", "hi"]},
                },
                "indexes": [{"name": "source_idx"}],
            },
            "metadata": {"version": 7, "flags": [True, False]},
        }

    def test_upgrade_changes_only_nullable_and_deep_copies(self):
        schema = self.make_schema()
        result = upgrade(schema)
        expected = self.make_schema()
        expected["documents"]["source"]["nullable"] = True
        self.assertEqual(result, expected)
        self.assertEqual(schema["documents"]["source"]["nullable"], "previous")
        self.assertIsNot(result, schema)
        self.assertIsNot(result["documents"], schema["documents"])
        self.assertIsNot(result["documents"]["source"], schema["documents"]["source"])
        self.assertIsNot(result["documents"]["source"]["options"], schema["documents"]["source"]["options"])
        self.assertIsNot(result["documents"]["source"]["options"]["languages"], schema["documents"]["source"]["options"]["languages"])
        self.assertIsNot(result["documents"]["indexes"], schema["documents"]["indexes"])
        self.assertIsNot(result["metadata"], schema["metadata"])
        result["metadata"]["flags"].append("new")
        self.assertEqual(schema["metadata"]["flags"], [True, False])

    def test_downgrade_adds_absent_nullable(self):
        schema = {"documents": {"source": {"type": "text"}}, "other": [1, 2]}
        result = downgrade(schema)
        self.assertEqual(result, {
            "documents": {"source": {"type": "text", "nullable": False}},
            "other": [1, 2],
        })
        self.assertNotIn("nullable", schema["documents"]["source"])
        self.assertIsNot(result["other"], schema["other"])

    def test_operations_are_idempotent(self):
        once_up = upgrade(self.make_schema())
        self.assertEqual(upgrade(once_up), once_up)
        once_down = downgrade(self.make_schema())
        self.assertEqual(downgrade(once_down), once_down)

    def test_missing_required_keys(self):
        with self.assertRaises(KeyError):
            upgrade({})
        with self.assertRaises(KeyError):
            downgrade({"documents": {}})

    def test_non_mapping_at_each_required_level(self):
        for operation in (upgrade, downgrade):
            for schema in (None, [], {"documents": []}, {"documents": {"source": []}}):
                with self.subTest(operation=operation.__name__, schema=schema):
                    with self.assertRaises(TypeError):
                        operation(schema)


if __name__ == "__main__":
    unittest.main()

